import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

export default function Dashboard() {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [sessions, setSessions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showAchievement, setShowAchievement] = useState(false);
  const [activeView, setActiveView] = useState('dashboard');
  const [filterTutor, setFilterTutor] = useState('all');
  const [filterPeriod, setFilterPeriod] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [studyGoal, setStudyGoal] = useState(localStorage.getItem('studyGoal') || '10');
  const [quickNote, setQuickNote] = useState('');
  const [notesFilter, setNotesFilter] = useState('all');
  const [activityFilter, setActivityFilter] = useState('7d');
  const [heatmapFilter, setHeatmapFilter] = useState('6m');
  const [notesKey, setNotesKey] = useState(0);

  useEffect(() => {
    loadUserData();
    loadSessions();
  }, []);

  useEffect(() => {
    if (sessions.length >= 5 && !localStorage.getItem('achievement_5sessions')) {
      setShowAchievement(true);
      localStorage.setItem('achievement_5sessions', 'true');
      setTimeout(() => setShowAchievement(false), 5000);
    }
  }, [sessions.length]);

  const loadUserData = () => {
    const userData = localStorage.getItem('currentUser');
    if (userData) {
      setUser(JSON.parse(userData));
    }
  };

  const loadSessions = async () => {
    try {
      const token = localStorage.getItem('authToken');
      if (!token) {
        console.log('No token found');
        setLoading(false);
        return;
      }

      const response = await fetch('http://localhost:8000/api/sessions', {
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      });

      if (response.ok) {
        const data = await response.json();
        console.log('✅ Sessions loaded:', data);
        setSessions(data);
      } else {
        console.error('❌ Failed to load sessions:', response.status);
      }
    } catch (error) {
      console.error('❌ Error loading sessions:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate('/auth', { replace: true });
  };

  const handleStartSession = (tutorId, subject) => {
    const roomId = `room_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    console.log('🚀 Starting NEW session with tutorId:', tutorId, 'subject:', subject);
    navigate(`/video/${roomId}`, { 
      state: { 
        tutorId: tutorId, 
        subject: subject, 
        resuming: false 
      },
      replace: true
    });
  };

  const handleResumeSession = (session) => {
    navigate(`/video/${session.session_id}`, { 
      state: { 
        tutorId: session.tutor_id,
        subject: session.subject, 
        resuming: true 
      },
      replace: true
    });
  };

  const handleSaveGoal = () => {
    localStorage.setItem('studyGoal', studyGoal);
    alert('Weekly goal updated!');
  };

  const handleSaveNote = () => {
    if (!quickNote.trim()) return;
    const notes = JSON.parse(localStorage.getItem('quickNotes') || '[]');
    notes.unshift({
      id: Date.now(),
      text: quickNote,
      date: new Date().toISOString()
    });
    localStorage.setItem('quickNotes', JSON.stringify(notes));
    setQuickNote('');
